function bytesToHex(bytes){
  var s='';
  for(var i=0;i<bytes.length;i++) s += ('0'+(bytes[i]&255).toString(16)).slice(-2);
  return s;
}

function hmacSha256Hex(key, msg){
  var kb = utf8Bytes(key);
  if (kb.length > 64) kb = sha256Bytes(kb);
  while (kb.length < 64) kb.push(0);
  var ipad = [], opad = [];
  for (var i = 0; i < 64; i++){ ipad.push(kb[i] ^ 0x36); opad.push(kb[i] ^ 0x5c); }
  var inner = sha256Bytes(ipad.concat(utf8Bytes(msg)));
  return bytesToHex(sha256Bytes(opad.concat(inner)));
}

var WH_PROVIDERS = {
  stripe:  { header:'Stripe-Signature', scheme:'t=<ts>,v1=<hex>', payload:'<ts>.<body>', tolerance:300 },
  github:  { header:'X-Hub-Signature-256', scheme:'sha256=<hex>', payload:'<body>', tolerance:0 },
  shopify: { header:'X-Shopify-Hmac-Sha256', scheme:'<base64>', payload:'<body>', tolerance:0 },
  slack:   { header:'X-Slack-Signature', scheme:'v0=<hex>', payload:'v0:<ts>:<body>', tolerance:300 },
  generic: { header:'X-Signature', scheme:'<hex>', payload:'<body>', tolerance:300 }
};

function signPayload(provider, secret, body, ts){
  var p = WH_PROVIDERS[provider];
  if (!p) return { value:'', error:'unknown provider: ' + provider };
  var base;
  if (provider === 'stripe') base = String(ts) + '.' + body;
  else if (provider === 'slack') base = 'v0:' + String(ts) + ':' + body;
  else base = body;
  var hex = hmacSha256Hex(secret, base);
  var header;
  if (provider === 'stripe') header = 't=' + ts + ',v1=' + hex;
  else if (provider === 'github') header = 'sha256=' + hex;
  else if (provider === 'slack') header = 'v0=' + hex;
  else header = hex;
  return { value:header, base:base, hex:hex, error:null };
}

function extractHex(provider, header){
  var h = String(header == null ? '' : header).trim();
  if (!h) return '';
  if (provider === 'stripe'){
    var parts = h.split(',');
    for (var i = 0; i < parts.length; i++){
      var kv = parts[i].split('=');
      if (kv[0].trim() === 'v1') return kv.slice(1).join('=').trim().toLowerCase();
    }
    return '';
  }
  if (h.indexOf('=') >= 0) return h.slice(h.indexOf('=') + 1).trim().toLowerCase();
  return h.toLowerCase();
}

function extractTs(header){
  var m = /(?:^|,)\s*t=(\d+)/.exec(String(header == null ? '' : header));
  return m ? parseInt(m[1], 10) : null;
}

function timingSafeEqual(a, b){
  var x = String(a || ''), y = String(b || '');
  if (x.length !== y.length) return false;
  var diff = 0;
  for (var i = 0; i < x.length; i++) diff |= (x.charCodeAt(i) ^ y.charCodeAt(i));
  return diff === 0;
}

function verifyWebhook(opt){
  opt = opt || {};
  var provider = opt.provider || 'generic';
  var p = WH_PROVIDERS[provider];
  if (!p) return { ok:false, reason:'unknown provider', checks:[] };
  var checks = [];
  var got = extractHex(provider, opt.header);
  if (!got) return { ok:false, reason:'签名头解析失败', checks:[{name:'解析签名头', pass:false, note:'未找到十六进制摘要'}] };
  checks.push({ name:'解析签名头', pass:true, note:got.slice(0, 16) + '…' });
  var ts = extractTs(opt.header);
  if (ts === null && opt.timestamp != null) ts = parseInt(opt.timestamp, 10);
  var tol = opt.tolerance == null ? p.tolerance : opt.tolerance;
  if (tol > 0 && ts != null && opt.now != null){
    var age = Math.abs(parseInt(opt.now, 10) - ts);
    var fresh = age <= tol;
    checks.push({ name:'重放窗口', pass:fresh, note:'age ' + age + 's / 容忍 ' + tol + 's' });
    if (!fresh) return { ok:false, reason:'时间戳超出容忍窗口，疑似重放', checks:checks, age:age };
  }
  var sig = signPayload(provider, opt.secret || '', opt.body == null ? '' : opt.body, ts == null ? 0 : ts);
  var match = timingSafeEqual(got, sig.hex);
  checks.push({ name:'HMAC 比对', pass:match, note:match ? '摘要一致' : '期望 ' + sig.hex.slice(0, 16) + '…' });
  return { ok:match, reason: match ? '签名有效' : 'HMAC 不匹配（密钥或原文有误）', checks:checks, expected:sig.hex, got:got, base:sig.base };
}

function retrySchedule(opt){
  opt = opt || {};
  var attempts = parseInt(opt.attempts, 10);
  if (!isFinite(attempts)) attempts = 5;
  attempts = Math.max(1, Math.min(20, attempts));
  var base = parseFloat(opt.base);
  if (!isFinite(base)) base = 1;
  base = Math.max(0.1, base);
  var factor = Math.max(1, parseFloat(opt.factor) || 2);
  var cap = Math.max(base, parseFloat(opt.cap) || 3600);
  var jitter = opt.jitter || 'full';
  var rows = [], elapsed = 0;
  for (var i = 0; i < attempts; i++){
    var raw = base * Math.pow(factor, i);
    var d = Math.min(cap, raw);
    var lo = d, hi = d;
    if (jitter === 'full'){ lo = 0; hi = d; }
    else if (jitter === 'equal'){ lo = d / 2; hi = d; }
    else if (jitter === 'decorrelated'){ lo = base; hi = Math.min(cap, d * 3); }
    var avg = (lo + hi) / 2;
    elapsed += avg;
    rows.push({ attempt:i + 1, delay:round2(d), min:round2(lo), max:round2(hi), avg:round2(avg), elapsed:round2(elapsed), capped: raw > cap });
  }
  return { rows:rows, total:round2(elapsed), totalHuman:humanDuration(elapsed), capped: rows.some(function(r){ return r.capped; }) };
}

function round2(n){ return Math.round(n * 100) / 100; }

function humanDuration(sec){
  var s = Math.round(sec);
  if (s < 60) return s + ' 秒';
  if (s < 3600) return Math.floor(s / 60) + ' 分 ' + (s % 60) + ' 秒';
  var h = Math.floor(s / 3600), m = Math.floor((s % 3600) / 60);
  if (s < 86400) return h + ' 小时 ' + m + ' 分';
  return Math.floor(s / 86400) + ' 天 ' + Math.floor((s % 86400) / 3600) + ' 小时';
}

function deliverySuccess(successRate, attempts){
  var p = Math.max(0, Math.min(1, parseFloat(successRate)));
  var n = Math.max(1, parseInt(attempts, 10) || 1);
  var fail = Math.pow(1 - p, n);
  return { value: Math.round((1 - fail) * 10000) / 10000, lostPerMillion: Math.round(fail * 1000000) };
}

function lintPayload(text, opt){
  opt = opt || {};
  var issues = [], body = String(text == null ? '' : text);
  var bytes = utf8Bytes(body).length;
  if (!body.trim()) issues.push({ level:'bad', msg:'负载为空，接收端无法区分心跳与事件' });
  var parsed = null, ok = true;
  try { parsed = JSON.parse(body); } catch (e){ ok = false; }
  if (body.trim() && !ok) issues.push({ level:'bad', msg:'不是合法 JSON：' + '接收端解析将失败' });
  if (bytes > 1048576) issues.push({ level:'bad', msg:'负载 ' + fmtBytes(bytes) + ' 超过 1 MB，多数网关会截断' });
  else if (bytes > 262144) issues.push({ level:'warn', msg:'负载 ' + fmtBytes(bytes) + ' 偏大，建议只传 ID 由消费方回查' });
  if (ok && parsed && typeof parsed === 'object' && !Array.isArray(parsed)){
    if (!parsed.id && !parsed.event_id && !parsed.eventId) issues.push({ level:'warn', msg:'缺少事件 ID 字段，消费方无法幂等去重' });
    if (!parsed.type && !parsed.event && !parsed.event_type) issues.push({ level:'warn', msg:'缺少事件类型字段，消费方需要靠猜路由' });
    if (!parsed.created && !parsed.timestamp && !parsed.created_at) issues.push({ level:'warn', msg:'缺少时间戳字段，乱序投递时无法排序' });
  }
  if (/"(password|secret|token|api_?key|authorization)"\s*:/i.test(body)) issues.push({ level:'bad', msg:'负载疑似包含明文凭据字段' });
  if (Array.isArray(parsed) && parsed.length > 100) issues.push({ level:'warn', msg:'一次投递 ' + parsed.length + ' 条事件，建议拆分批次' });
  return { bytes:bytes, human:fmtBytes(bytes), json:ok, issues:issues, score: scoreIssues(issues) };
}

function scoreIssues(issues){
  var s = 100;
  for (var i = 0; i < issues.length; i++) s -= (issues[i].level === 'bad' ? 25 : 10);
  return Math.max(0, s);
}

function fmtBytes(n){
  if (n < 1024) return n + ' B';
  if (n < 1048576) return (Math.round(n / 102.4) / 10) + ' KB';
  return (Math.round(n / 104857.6) / 10) + ' MB';
}

function curlCommand(opt){
  opt = opt || {};
  var provider = opt.provider || 'generic';
  var p = WH_PROVIDERS[provider] || WH_PROVIDERS.generic;
  var sig = signPayload(provider, opt.secret || '', opt.body || '{}', opt.timestamp || 0);
  var lines = ["curl -sS -X POST '" + (opt.url || 'https://example.com/hook') + "' \\"];
  lines.push("  -H 'Content-Type: application/json' \\");
  lines.push("  -H '" + p.header + ": " + sig.value + "' \\");
  lines.push("  --data-raw '" + String(opt.body || '{}').replace(/'/g, "'\\''") + "'");
  return lines.join('\n');
}

